//! The 187 DrawingML preset geometries (ST_ShapeType).
//!
//! The definitions are transcribed from ECMA-376 Part 1 Annex D (`presetShapeDefinitions.xml`,
//! Ecma International, a royalty-free standard). `data.rs` is generated by
//! `tools/port-presets.py` from the reference transcription in
//! `reference/ts-core/ooxml/src/drawingml/presets/`; do not edit it by hand
//! (`python3 -I tools/port-presets.py --check` verifies it is current).
//!
//! Each preset is compiled once, on first use, by the same engine that evaluates `a:custGeom`.

use std::sync::OnceLock;

use super::geometry::{
    AdjustHandleDef, CompiledGeometry, ConnectionSiteDef, GeometryDef, GeometryError, GuideDef,
    PathCommand, PathDef, ResolvedGeometry,
};
use crate::st::PathFillMode;

#[rustfmt::skip]
mod data;

/// Preset geometries grouped as in Office's Insert ▸ Shapes gallery.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum PresetCategory {
    /// Rectangles, ovals, polygons, brackets and the other basic shapes.
    Basic,
    /// Lines and connectors.
    LinesConnectors,
    /// Block arrows.
    Arrows,
    /// Flowchart symbols.
    Flowchart,
    /// Stars, seals, ribbons, scrolls and waves.
    StarsBanners,
    /// Callouts.
    Callouts,
    /// Equation shapes.
    Math,
    /// Action buttons.
    ActionButtons,
}

impl PresetCategory {
    /// Every category, in gallery order.
    pub const ALL: [PresetCategory; 8] = [
        PresetCategory::Basic,
        PresetCategory::LinesConnectors,
        PresetCategory::Arrows,
        PresetCategory::Flowchart,
        PresetCategory::StarsBanners,
        PresetCategory::Callouts,
        PresetCategory::Math,
        PresetCategory::ActionButtons,
    ];
}

/// An adjust handle as transcribed.
#[derive(Debug, Clone, Copy)]
enum PresetHandle {
    Xy {
        gd_ref_x: Option<&'static str>,
        min_x: Option<&'static str>,
        max_x: Option<&'static str>,
        gd_ref_y: Option<&'static str>,
        min_y: Option<&'static str>,
        max_y: Option<&'static str>,
        pos: (&'static str, &'static str),
    },
    Polar {
        gd_ref_r: Option<&'static str>,
        min_r: Option<&'static str>,
        max_r: Option<&'static str>,
        gd_ref_ang: Option<&'static str>,
        min_ang: Option<&'static str>,
        max_ang: Option<&'static str>,
        pos: (&'static str, &'static str),
    },
}

/// A path command as transcribed.
#[derive(Debug, Clone, Copy)]
enum PresetCmd {
    M(&'static str, &'static str),
    L(&'static str, &'static str),
    A(&'static str, &'static str, &'static str, &'static str),
    Q(&'static str, &'static str, &'static str, &'static str),
    C(
        &'static str,
        &'static str,
        &'static str,
        &'static str,
        &'static str,
        &'static str,
    ),
    Z,
}

/// A path as transcribed.
#[derive(Debug, Clone, Copy)]
struct PresetPath {
    w: Option<f64>,
    h: Option<f64>,
    fill: Option<PathFillMode>,
    stroke: Option<bool>,
    extrusion_ok: Option<bool>,
    cmds: &'static [PresetCmd],
}

/// One preset as transcribed.
#[derive(Debug, Clone, Copy)]
struct PresetDef {
    name: &'static str,
    category: PresetCategory,
    av: &'static [(&'static str, &'static str)],
    gd: &'static [(&'static str, &'static str)],
    ah: &'static [PresetHandle],
    cxn: &'static [(&'static str, &'static str, &'static str)],
    rect: Option<(&'static str, &'static str, &'static str, &'static str)>,
    path: &'static [PresetPath],
}

fn s(v: &str) -> String {
    v.to_owned()
}
fn opt(v: Option<&str>) -> Option<String> {
    v.map(str::to_owned)
}

impl PresetDef {
    fn geometry_def(&self) -> GeometryDef {
        GeometryDef {
            av: self.av.iter().map(|(n, f)| GuideDef::new(n, f)).collect(),
            gd: self.gd.iter().map(|(n, f)| GuideDef::new(n, f)).collect(),
            ah: self
                .ah
                .iter()
                .map(|h| match *h {
                    PresetHandle::Xy {
                        gd_ref_x,
                        min_x,
                        max_x,
                        gd_ref_y,
                        min_y,
                        max_y,
                        pos,
                    } => AdjustHandleDef::Xy {
                        gd_ref_x: opt(gd_ref_x),
                        min_x: opt(min_x),
                        max_x: opt(max_x),
                        gd_ref_y: opt(gd_ref_y),
                        min_y: opt(min_y),
                        max_y: opt(max_y),
                        pos: (s(pos.0), s(pos.1)),
                    },
                    PresetHandle::Polar {
                        gd_ref_r,
                        min_r,
                        max_r,
                        gd_ref_ang,
                        min_ang,
                        max_ang,
                        pos,
                    } => AdjustHandleDef::Polar {
                        gd_ref_r: opt(gd_ref_r),
                        min_r: opt(min_r),
                        max_r: opt(max_r),
                        gd_ref_ang: opt(gd_ref_ang),
                        min_ang: opt(min_ang),
                        max_ang: opt(max_ang),
                        pos: (s(pos.0), s(pos.1)),
                    },
                })
                .collect(),
            cxn: self
                .cxn
                .iter()
                .map(|(a, x, y)| ConnectionSiteDef {
                    ang: s(a),
                    x: s(x),
                    y: s(y),
                })
                .collect(),
            rect: self.rect.map(|(l, t, r, b)| [s(l), s(t), s(r), s(b)]),
            path: self
                .path
                .iter()
                .map(|p| PathDef {
                    w: p.w,
                    h: p.h,
                    fill: p.fill,
                    stroke: p.stroke,
                    extrusion_ok: p.extrusion_ok,
                    cmds: p
                        .cmds
                        .iter()
                        .map(|c| match *c {
                            PresetCmd::M(x, y) => PathCommand::MoveTo(s(x), s(y)),
                            PresetCmd::L(x, y) => PathCommand::LineTo(s(x), s(y)),
                            PresetCmd::A(wr, hr, st, sw) => PathCommand::ArcTo {
                                wr: s(wr),
                                hr: s(hr),
                                st_ang: s(st),
                                sw_ang: s(sw),
                            },
                            PresetCmd::Q(a, b, c, d) => {
                                PathCommand::QuadBezTo([s(a), s(b), s(c), s(d)])
                            }
                            PresetCmd::C(a, b, c, d, e, f) => {
                                PathCommand::CubicBezTo([s(a), s(b), s(c), s(d), s(e), s(f)])
                            }
                            PresetCmd::Z => PathCommand::Close,
                        })
                        .collect(),
                })
                .collect(),
        }
    }
}

/// The number of preset geometries in ECMA-376.
pub const PRESET_COUNT: usize = data::PRESET_COUNT;

static COMPILED: [OnceLock<Result<CompiledGeometry, GeometryError>>; data::PRESET_COUNT] =
    [const { OnceLock::new() }; data::PRESET_COUNT];

fn index_of(name: &str) -> Option<usize> {
    data::PRESETS.binary_search_by(|p| p.name.cmp(name)).ok()
}

/// Every ST_ShapeType value, sorted.
pub fn preset_names() -> impl ExactSizeIterator<Item = &'static str> {
    data::PRESETS.iter().map(|p| p.name)
}

/// True for an ST_ShapeType value.
#[must_use]
pub fn is_preset_shape_type(name: &str) -> bool {
    index_of(name).is_some()
}

/// The gallery category of a preset.
#[must_use]
pub fn preset_category(name: &str) -> Option<PresetCategory> {
    index_of(name).map(|i| data::PRESETS[i].category)
}

/// The presets of a category, sorted by name.
pub fn presets_in(category: PresetCategory) -> impl Iterator<Item = &'static str> {
    data::PRESETS
        .iter()
        .filter(move |p| p.category == category)
        .map(|p| p.name)
}

/// The definition of a preset (as `a:custGeom` would hold it), for example to convert a preset
/// shape to a freeform when the user edits its points.
#[must_use]
pub fn preset_definition(name: &str) -> Option<GeometryDef> {
    index_of(name).map(|i| data::PRESETS[i].geometry_def())
}

/// The compiled preset (compiled on first use and cached for the life of the process).
///
/// # Errors
/// [`GeometryError::UnknownPreset`] for a name outside ST_ShapeType.
pub fn compiled_preset(name: &str) -> Result<&'static CompiledGeometry, GeometryError> {
    let i = index_of(name).ok_or_else(|| GeometryError::UnknownPreset(name.to_owned()))?;
    COMPILED[i]
        .get_or_init(|| data::PRESETS[i].geometry_def().compile())
        .as_ref()
        .map_err(Clone::clone)
}

/// Evaluates a preset for a `w` × `h` shape with optional adjust values (`[("adj", 25000.0)]`, as
/// stored in `a:prstGeom/a:avLst`): paths with fill/stroke flags, text rectangle, connection
/// sites and handles.
///
/// # Errors
/// [`GeometryError::UnknownPreset`].
pub fn preset_geometry(
    name: &str,
    w: f64,
    h: f64,
    adjustments: &[(&str, f64)],
) -> Result<ResolvedGeometry, GeometryError> {
    Ok(compiled_preset(name)?.resolve(w, h, adjustments))
}

/// SVG path data (all of the preset's paths joined) for a `w` × `h` shape.
///
/// # Errors
/// [`GeometryError::UnknownPreset`].
pub fn preset_to_svg_path(
    name: &str,
    w: f64,
    h: f64,
    adjustments: &[(&str, f64)],
) -> Result<String, GeometryError> {
    Ok(preset_geometry(name, w, h, adjustments)?.to_svg())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_table_is_sorted_unique_and_complete() {
        assert_eq!(PRESET_COUNT, 187);
        assert_eq!(data::PRESETS.len(), 187);
        assert!(
            data::PRESETS.windows(2).all(|w| w[0].name < w[1].name),
            "sorted and unique"
        );
        let per_category: usize = PresetCategory::ALL
            .iter()
            .map(|c| presets_in(*c).count())
            .sum();
        assert_eq!(per_category, 187);
    }

    #[test]
    fn every_preset_compiles() {
        for name in preset_names() {
            assert!(compiled_preset(name).is_ok(), "{name}");
        }
    }
}
